window.EW=window.EW||{pages:{}};window.EW.pages["wiki-les-lieux--le-chateau"]={"html":"<p>Les lieux intérieurs du château d'Elderwood et les salles communes.<\/p><h3 id=\"la-bibliotheque\">La Bibliothèque<\/h3><p>Manuels, grimoires anciens et sections interdites, gérés par un bibliothécaire et des fées des bois.<\/p><h3 id=\"l-infirmerie-grimshaw\">L'Infirmerie Grimshaw<\/h3><p>Nommée en hommage à Edith Grimshaw, ancienne médicomage d'Elderwood (voir <a href=\"#/p/wiki-personnages\">Personnages illustres<\/a>).<\/p><h3 id=\"les-jardins\">Les Jardins<\/h3><p>Modifiés par la proximité de la <a href=\"#/p/wiki-les-lieux--la-source\">Source<\/a>, lieu d'étude et de repos à l'ombre des grands arbres.<\/p><h3 id=\"la-grande-voliere\">La Grande Volière<\/h3><p>Tour ouverte où nichent chouettes, corbeaux et faucons messagers.<\/p><h3 id=\"le-pavillon-des-compagnons\">Le Pavillon des Compagnons<\/h3><p>Abrite les familiers des élèves, géré par le garde-chasse et le professeur de magizoologie.<\/p><h3 id=\"l-atelier-des-catalyseurs\">L'Atelier des Catalyseurs<\/h3><p>Salle technique où les élèves apprennent à entretenir et réparer baguettes, sceptres et bâtons.<\/p><h3 id=\"la-forge-runique\">La Forge Runique<\/h3><p>Profondément enfouie sous le château, réservée aux élèves avancés.<\/p><h3 id=\"les-cuisines-hearthbane\">Les Cuisines Hearthbane<\/h3><p>Vastes et toujours en mouvement, situées sous la Grande Salle.<\/p><h3 id=\"la-grande-salle\">La Grande Salle<\/h3><p>Seul lieu où toutes les maisons se retrouvent sous le même toit.<\/p><h3 id=\"les-salles-communes\">Les salles communes<\/h3><ul><li><strong>L'Observatoire des Hautes-Vues<\/strong> (<a href=\"#/p/wiki-les-maisons--maison-falcon\">maison Falcon<\/a>) : nichée dans les plus hautes tours du château, accessible par un pont suspendu. Falcon y aurait conçu les premières bases du système d'apprentissage.<\/li><li><strong>La Veillée Bleue<\/strong> (<a href=\"#/p/wiki-les-maisons--maison-aerwyn\">maison Aerwyn<\/a>) : éclairée par un toit de verre incassable, elle expose les armures des anciens défenseurs du château.<\/li><li><strong>Le Salon des Ombres<\/strong> (<a href=\"#/p/wiki-les-maisons--maison-venatrix\">maison Venatrix<\/a>) : nichée dans les sous-sols, ouverte sur les profondeurs du lac par deux grandes baies vitrées.<\/li><li><strong>Le Grand Foyer<\/strong> (<a href=\"#/p/wiki-les-maisons--maison-brumval\">maison Brumval<\/a>) : la plus chaleureuse du château, réchauffée par un feu qui ne s'éteint jamais.<\/li><\/ul>","toc":[{"id":"la-bibliotheque","t":"La Bibliothèque","l":3},{"id":"l-infirmerie-grimshaw","t":"L'Infirmerie Grimshaw","l":3},{"id":"les-jardins","t":"Les Jardins","l":3},{"id":"la-grande-voliere","t":"La Grande Volière","l":3},{"id":"le-pavillon-des-compagnons","t":"Le Pavillon des Compagnons","l":3},{"id":"l-atelier-des-catalyseurs","t":"L'Atelier des Catalyseurs","l":3},{"id":"la-forge-runique","t":"La Forge Runique","l":3},{"id":"les-cuisines-hearthbane","t":"Les Cuisines Hearthbane","l":3},{"id":"la-grande-salle","t":"La Grande Salle","l":3},{"id":"les-salles-communes","t":"Les salles communes","l":3}]};
